{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE TABLE IF NOT EXISTS medmongers_db.maplemonk.INYOU_UTM_MAPPING ( UTM_SOURCE VARCHAR(16777216), UTM_MEDIUM VARCHAR(16777216), CHANNEL VARCHAR(16777216)); CREATE OR REPLACE TABLE medmongers_db.maplemonk.InYou_Shopify_All_customers AS select *,\'Shopify_inyou\' AS Shop_Name from medmongers_db.maplemonk.Shopify_inyou_CUSTOMERS ; create or replace table medmongers_db.maplemonk.inyou_Shopify_UTM_Parameters as select ShopifyQL.* ,upper(coalesce(UTM_MAPPING.CHANNEL,UTM_MAPPING_REF.CHANNEL,ShopifyQL.ShopifyQL_Unmapped_Last_Source)) as ShopifyQL_MAPPED_CHANNEL ,upper(coalesce(UTM_MAPPING.UTM_SOURCE,UTM_MAPPING_REF.UTM_SOURCE,ShopifyQL.ShopifyQL_Unmapped_Last_Source)) as ShopifyQL_MAPPED_SOURCE from (select * from (select A.id ,A.name ,A.createdat ,coalesce(CUSTOMERJOURNEYSUMMARY:\"momentsCount\":\"count\" ,customerjourneysummary:\"momentsCount\") Moments_Count ,replace(A.customerjourneysummary:\"daysToConversion\",\'\"\',\'\') DaysToConvert ,replace(A.CUSTOMERJOURNEYSUMMARY:\"lastVisit\":\"utmParameters\":\"source\",\'\"\',\'\') LastVisit_UTM_Source ,replace(A.CUSTOMERJOURNEYSUMMARY:\"lastVisit\":\"source\",\'\"\',\'\') LastVisit_NON_UTM_Source ,replace(A.CUSTOMERJOURNEYSUMMARY:\"lastVisit\":\"utmParameters\":\"campaign\",\'\"\',\'\') LastVisit_UTM_Campaign ,replace(A.CUSTOMERJOURNEYSUMMARY:\"lastVisit\":\"utmParameters\":\"content\",\'\"\',\'\') LastVisit_UTM_content ,replace(A.CUSTOMERJOURNEYSUMMARY:\"firstVisit\":\"utmParameters\":\"source\",\'\"\',\'\') FirstVisit_UTM_Source ,replace(A.CUSTOMERJOURNEYSUMMARY:\"firstVisit\":\"utmParameters\":\"medium\",\'\"\',\'\') FirstVisit_UTM_Medium ,replace(A.CUSTOMERJOURNEYSUMMARY:\"firstVisit\":\"utmParameters\":\"campaign\",\'\"\',\'\') FirstVisit_UTM_Campaign ,replace(A.CUSTOMERJOURNEYSUMMARY:\"firstVisit\":\"utmParameters\":\"content\",\'\"\',\'\') FirstVisit_UTM_content ,replace(B.Value:\"id\",\'gid://shopify/CustomerVisit/\',\'\') Moment_ID ,replace(B.value:\"utmParameters\":\"source\",\'\"\',\'\') Last_Moment_UTM_Source ,replace(B.value:\"utmParameters\":\"medium\",\'\"\',\'\') Last_Moment_UTM_Medium ,case when Moments_Count >1 then LastVisit_UTM_Source else FirstVisit_UTM_Source end CJSummary_utm_source ,referrerdisplaytext Referrer_Name ,customerjourneysummary ,customerjourney ,landingpageurl ,coalesce(Last_Moment_UTM_Source,LastVisit_NON_UTM_Source) ShopifyQL_Unmapped_Last_Source ,rank() over (partition by name order by MOMENT_ID desc) rw from medmongers_db.maplemonk.Shopify_inyou_UTM_PARAMETERS A, lateral flatten (INPUT => customerjourney:\"moments\",OUTER => TRUE) B ) where rw=1 ) ShopifyQL left join (select * from (select *, row_number() over (partition by lower(utm_source) order by 1) rw from medmongers_db.maplemonk.inyou_utm_mapping) where rw=1 and utm_source is not null ) UTM_MAPPING on lower(ShopifyQL.ShopifyQL_Unmapped_Last_Source) = lower(UTM_MAPPING.utm_source) left join (select * from (select * , row_number() over (partition by lower(utm_source) order by 1) rw from medmongers_db.maplemonk.inyou_utm_mapping) where rw=1 and utm_source is not null ) UTM_MAPPING_REF on lower(ShopifyQL.referrer_name) = lower(UTM_MAPPING_REF.utm_source) left join (select * from (select * , row_number() over (partition by lower(utm_source) order by 1) rw from medmongers_db.maplemonk.inyou_utm_mapping) where rw=1 and utm_source is not null ) UTM_MAPPING_FIRST_CLICK on lower(ShopifyQL.FirstVisit_UTM_Source) = lower(UTM_MAPPING_FIRST_CLICK.utm_source) ; create or replace table medmongers_db.maplemonk.inyou_GOKWIK_SOURCE as With GO_KWIK as ( WITH utm_source_cte AS ( SELECT S.id, UPPER(A.value:\"value\") AS utm_source FROM medmongers_db.maplemonk.Shopify_inyou_ORDERS S, LATERAL FLATTEN(INPUT => note_attributes) A where (LOWER(S.note_attributes) LIKE \'%gokwik%\' or LOWER(S.tags) LIKE \'%gokwik%\') AND LOWER(A.value:\"name\") = \'utm_source\' ), utm_medium_cte AS ( SELECT S.id, UPPER(A.value:\"value\") AS utm_medium FROM medmongers_db.maplemonk.Shopify_inyou_ORDERS S, LATERAL FLATTEN(INPUT => note_attributes) A where (LOWER(S.note_attributes) LIKE \'%gokwik%\' or LOWER(S.tags) LIKE \'%gokwik%\') AND LOWER(A.value:\"name\") = \'utm_medium\' ), utm_campaign_cte AS ( SELECT S.id, UPPER(A.value:\"value\") AS utm_campaign FROM medmongers_db.maplemonk.Shopify_inyou_ORDERS S, LATERAL FLATTEN(INPUT => note_attributes) A where (LOWER(S.note_attributes) LIKE \'%gokwik%\' or LOWER(S.tags) LIKE \'%gokwik%\') AND LOWER(A.value:\"name\") = \'utm_campaign\' ), utm_content_cte AS ( SELECT S.id ,UPPER(A.value:\"value\") AS utm_content FROM medmongers_db.maplemonk.Shopify_inyou_ORDERS S, LATERAL FLATTEN(INPUT => note_attributes) A where (LOWER(S.note_attributes) LIKE \'%gokwik%\' or LOWER(S.tags) LIKE \'%gokwik%\') AND LOWER(A.value:\"name\") = \'utm_content\' ) SELECT S.id, S.tags, source_cte.utm_source AS GOKWIK_UTM_SOURCE, medium_cte.utm_medium AS GOKWIK_UTM_MEDIUM, campaign_cte.utm_campaign AS GOKWIK_UTM_CAMPAIGN, content_cte.utm_content AS GOKWIK_UTM_CONTENT FROM medmongers_db.maplemonk.Shopify_inyou_ORDERS S LEFT JOIN utm_source_cte source_cte ON S.id = source_cte.id LEFT JOIN utm_medium_cte medium_cte ON S.id = medium_cte.id LEFT JOIN utm_campaign_cte campaign_cte ON S.id = campaign_cte.id LEFT JOIN utm_content_cte content_cte ON S.id = content_cte.id WHERE LOWER(S.note_attributes) LIKE \'%gokwik%\' ) Select GO_KWIK.* ,coalesce(Upper(UTM_MAPPING.CHANNEL), upper(GOKWIK_UTM_MEDIUM)) as GOKWIK_MAPPED_CHANNEL ,coalesce(Upper(UTM_MAPPING.CHANNEL), upper(GOKWIK_UTM_SOURCE)) as GOKWIK_MAPPED_SOURCE from GO_KWIK left join (select * from (select * , row_number() over (partition by lower(concat(ifnull(utm_source,\'\'),ifnull(utm_medium,\'\'))) order by 1) rw from medmongers_db.maplemonk.inyou_utm_mapping) where rw=1 and lower(concat(ifnull(utm_source,\'\'),ifnull(utm_medium,\'\'))) is not null ) UTM_MAPPING on lower(concat(ifnull(GO_KWIK.GOKWIK_UTM_SOURCE,\'\'),ifnull(GOKWIK_UTM_MEDIUM,\'\'))) = lower(concat(ifnull(UTM_MAPPING.utm_source,\'\'),ifnull(UTM_MAPPING.utm_medium,\'\'))) ; create or replace table medmongers_db.maplemonk.inyou_Shopify_All_orders as select AO.* ,UPPER(ShopifyQL.shopifyql_mapped_channel) shopifyql_mapped_channel ,UPPER(ShopifyQL.shopifyql_mapped_source) shopifyql_mapped_source ,UPPER(ShopifyQL.FIRSTVISIT_UTM_SOURCE) Shopifyql_FIRSTVISIT_UTM_SOURCE ,UPPER(ShopifyQL.FirstVisit_UTM_Campaign) Shopifyql_FIRSTVISIT_UTM_CAMPAIGN ,UPPER(ShopifyQL.FIRSTVISIT_UTM_content) Shopifyql_FIRSTVISIT_UTM_content ,upper(ShopifyQL.LastVisit_UTM_Campaign) Shopifyql_LAST_VISIT_UTM_CAMPAIGN ,UPPER(ShopifyQL.LAST_MOMENT_UTM_SOURCE) Shopifyql_LAST_MOMENT_UTM_SOURCE ,UPPER(ShopifyQL.LastVisit_NON_UTM_Source) Shopifyql_LAST_VISIT_NON_UTM_SOURCE ,UPPER(ShopifyQL.LAST_MOMENT_UTM_MEDIUM) Shopifyql_LAST_MOMENT_UTM_MEDIUM ,UPPER(ShopifyQL.FIRSTVISIT_UTM_MEDIUM) Shopifyql_FIRSTVISIT_UTM_MEDIUM ,div0(ShopifyQL.MOMENTS_COUNT,count(1) over (partition by AO.name order by 1)) MOMENTS_COUNT ,div0(ShopifyQL.DAYSTOCONVERT,count(1) over (partition by AO.name order by 1)) DAYSTOCONVERT ,UPPER(GOKWIK.GOKWIK_UTM_SOURCE) GOKWIK_UTM_SOURCE ,UPPER(GOKWIK.GOKWIK_UTM_MEDIUM) GOKWIK_UTM_MEDIUM ,UPPER(GOKWIK.GOKWIK_UTM_CONTENT) GOKWIK_UTM_CONTENT ,UPPER(GOKWIK.GOKWIK_MAPPED_CHANNEL) GOKWIK_MAPPED_CHANNEL ,UPPER(GOKWIK.GOKWIK_MAPPED_SOURCE) GOKWIK_MAPPED_SOURCE ,UPPER(Referrer_Name) Referrer_Name ,upper(landingpageurl) landingpageurl ,UPPER(GOKWIK.GOKWIK_UTM_CAMPAIGN) GOKWIK_UTM_CAMPAIGN ,UPPER(coalesce(GOKWIK_UTM_CAMPAIGN,LastVisit_UTM_Campaign)) FINAL_UTM_CAMPAIGN ,Upper(coalesce(GOKWIK_MAPPED_SOURCE,shopifyql_mapped_source,\'Direct\')) FINAL_UTM_SOURCE ,Upper(coalesce(GOKWIK_MAPPED_CHANNEL,shopifyql_mapped_channel,\'Direct\')) FINAL_UTM_CHANNEL ,UPPER(coalesce(ShopifyQL.LASTVISIT_UTM_content,GOKWIK.GOKWIK_UTM_CONTENT)) final_utm_content from (select * ,\'Shopify_inyou\' AS Shop_Name from medmongers_db.maplemonk.Shopify_inyou_ORDERS) AO left join (select * from (select *, row_number() over (partition by name order by 1) rwb from medmongers_db.maplemonk.inyou_Shopify_UTM_Parameters ) where rwb = 1 ) ShopifyQL on AO.name = ShopifyQL.name left join medmongers_db.maplemonk.inyou_GOKWIK_SOURCE GOKWIK on AO.ID = GOKWIK.ID ; ALTER TABLE medmongers_db.maplemonk.inyou_Shopify_All_orders RENAME COLUMN _AIRBYTE_Shopify_inyou_ORDERS_HASHID to _AIRBYTE_ORDERS_HASHID; CREATE OR REPLACE TABLE medmongers_db.maplemonk.inyou_Shopify_All_products AS select *,\'Shopify_inyou\' AS Shop_Name from medmongers_db.maplemonk.Shopify_inyou_PRODUCTS ; ALTER TABLE medmongers_db.maplemonk.inyou_Shopify_All_products RENAME COLUMN _AIRBYTE_Shopify_inyou_PRODUCTS_HASHID to _AIRBYTE_PRODUCTS_HASHID; CREATE OR REPLACE TABLE medmongers_db.maplemonk.inyou_Shopify_All_products_variants AS select *,\'Shopify_inyou\' AS Shop_Name from medmongers_db.maplemonk.Shopify_inyou_PRODUCTS_VARIANTS ; ALTER TABLE medmongers_db.maplemonk.inyou_SHOPIFY_ALL_PRODUCTS_VARIANTS RENAME COLUMN _AIRBYTE_Shopify_inyou_PRODUCTS_HASHID to _AIRBYTE_PRODUCTS_HASHID; CREATE OR REPLACE TABLE medmongers_db.maplemonk.inyou_Shopify_All_customers_addresses AS select distinct id, customer_id, city, province,\'Shopify_inyou\' AS Shop_Name from medmongers_db.maplemonk.Shopify_inyou_CUSTOMERS_ADDRESSES ; CREATE OR REPLACE TABLE medmongers_db.maplemonk.inyou_Shopify_All_orders_items_discount AS SELECT order_id, LINE_ITEM_ID, SUM(B.VALUE:amount::FLOAT) AS DISCOUNT FROM( SELECT id AS order_id, A.VALUE:id AS LINE_ITEM_ID, A.VALUE:discount_allocations AS discount_allocations FROM medmongers_db.maplemonk.inyou_Shopify_All_orders , LATERAL FLATTEN (INPUT => LINE_ITEMS)A)x,LATERAL FLATTEN (INPUT => x.discount_allocations)B GROUP BY ORDER_ID, LINE_ITEM_ID; CREATE OR REPLACE TABLE medmongers_db.maplemonk.inyou_Shopify_All_orders_items_tax AS SELECT order_id, LINE_ITEM_ID, SUM(B.VALUE:price::FLOAT) AS TAX, sum(B.VALUE:rate::float) as Tax_Rate FROM( SELECT id AS order_id, A.VALUE:id AS LINE_ITEM_ID, A.VALUE:tax_lines AS tax_lines FROM medmongers_db.maplemonk.inyou_SHOPIFY_ALL_ORDERS, LATERAL FLATTEN (INPUT => LINE_ITEMS)A)x,LATERAL FLATTEN (INPUT => x.tax_lines)B GROUP BY order_id, LINE_ITEM_ID; CREATE OR REPLACE TABLE medmongers_db.maplemonk.inyou_Shopify_All_Refunds AS SELECT Name, ID AS Order_ID, Shop_name, (replace(A.value:created_at,\'\"\',\'\'))::datetime as refund_date, C.value:line_item_id AS line_item_id, SUM(C.VALUE:quantity) AS quantity, SUM(C.VALUE:subtotal) AS subtotal FROM medmongers_db.maplemonk.inyou_SHOPIFY_ALL_ORDERS, LATERAL FLATTEN(INPUT => refunds)A, LATERAL FLATTEN(INPUT=>A.value)B, LATERAL FLATTEN(INPUT => B.value) C WHERE C.value:line_item_id IS NOT null GROUP BY Name, ID, Shop_name, A.value:created_at, C.value:line_item_id; CREATE OR REPLACE TABLE medmongers_db.maplemonk.inyou_Shopify_All_orders_fulfillment AS SELECT A.value:order_id AS order_id, B.value:id Line_Item_ID, replace(A.VALUE:tracking_number,\'\"\',\'\') as AWB, Upper(replace(A.VALUE:tracking_company,\'\"\',\'\')) as Courier, Upper(replace(A.VALUE:shipment_status,\'\"\',\'\')) as Shipping_status, replace(A.VALUE:updated_at,\'\"\',\'\') as shipping_status_update_date, replace(A.VALUE:tracking_url,\'\"\',\'\') as tracking_url, replace(A.VALUE:created_at,\'\"\',\'\') as Shipping_created_at FROM medmongers_db.maplemonk.inyou_SHOPIFY_ALL_ORDERS, LATERAL FLATTEN (INPUT => fulfillments)A,LATERAL FLATTEN (INPUT => A.value:line_items)B ; CREATE OR REPLACE TABLE medmongers_db.maplemonk.inyou_Shopify_All_discount_codes AS select ID, code from ( select ID, CODE from ( SELECT id, replace(A.value:code , \'\"\',\'\') code, row_number() over (partition by id order by code) rw FROM medmongers_db.maplemonk.inyou_SHOPIFY_ALL_ORDERS, LATERAL FLATTEN (INPUT => discount_codes) A )where rw=1)a ; CREATE OR REPLACE TABLE medmongers_db.maplemonk.inyou_Shopify_All_orders_items AS WITH CTE AS (SELECT SHOP_NAME, ID::VARCHAR(16777216) AS ORDER_ID, NAME AS ORDER_NAME, CUSTOMER, replace(customer:default_address:name,\'\"\',\'\') NAME, coalesce(phone, replace(customer:default_address:phone,\'\"\',\'\')) phone, coalesce(email, replace(customer:email,\'\"\',\'\')) email, replace(shipping_address:zip,\'\"\',\'\') pincode, tags, A.VALUE:id AS LINE_ITEM_ID, A.VALUE:sku::STRING AS SKU, A.VALUE:product_id::STRING AS PRODUCT_ID, A.VALUE:title::STRING AS PRODUCT_NAME, CURRENCY, CASE WHEN cancelled_at IS NOT NULL THEN \'CANCELLED\' ELSE \'Shopify_Processed\' END AS order_status, cancelled_at::DATETIME as cancelled_at, CREATED_AT::DATETIME AS order_timestamp, A.VALUE:price::FLOAT offer_price, A.VALUE:price::FLOAT * A.VALUE:quantity::FLOAT AS LINE_ITEM_SALES, (TOTAL_SHIPPING_PRICE_SET:presentment_money:amount::FLOAT/ COUNT(ORDER_ID) OVER(PARTITION BY ORDER_ID ORDER BY ORDER_ID)) AS SHIPPING_PRICE, A.value:price/(1+A.value:tax_lines:rate), A.VALUE:quantity::FLOAT as QUANTITY, \'Shopify\' AS Source, MOMENTS_COUNT, DAYSTOCONVERT, SHOPIFYQL_FIRSTVISIT_UTM_SOURCE, SHOPIFYQL_MAPPED_CHANNEL, SHOPIFYQL_LAST_MOMENT_UTM_SOURCE, Shopifyql_LAST_VISIT_NON_UTM_SOURCE, Shopifyql_LAST_MOMENT_UTM_MEDIUM, Shopifyql_FIRSTVISIT_UTM_MEDIUM, Shopifyql_FIRSTVISIT_UTM_CAMPAIGN, Shopifyql_LAST_VISIT_UTM_CAMPAIGN, FINAL_UTM_CHANNEL, FINAL_UTM_SOURCE, GOKWIK_UTM_MEDIUM, FINAL_UTM_CAMPAIGN, final_utm_content, landingpageurl, Referrer_Name, NULL as product_sub_category, payment_gateway_names, discount_codes FROM medmongers_db.maplemonk.inyou_SHOPIFY_ALL_ORDERS, LATERAL FLATTEN (INPUT => LINE_ITEMS)A) SELECT CTE.*, dc.code discount_code, IFNULL(T.TAX_RATE,0) AS TAX_RATE, IFNULL(D.DISCOUNT,0) AS DISCOUNT, CTE.LINE_ITEM_SALES AS GROSS_SALES_AFTER_TAX, CTE.LINE_ITEM_SALES/(1+IFNULL(T.TAX_RATE,0)) AS GROSS_SALES_BEFORE_TAX, IFNULL(D.DISCOUNT,0)/(1+IFNULL(T.TAX_RATE,0)) AS DISCOUNT_BEFORE_TAX, CTE.LINE_ITEM_SALES/(1+IFNULL(T.TAX_RATE,0)) - IFNULL(D.DISCOUNT,0)/(1+IFNULL(T.TAX_RATE,0)) AS NET_SALES_BEFORE_TAX, case when IFNULL(T.TAX,0) = 0 then CTE.LINE_ITEM_SALES*tax_rate else IFNULL(T.TAX,0) end AS TAX, IFNULL(T.TAX,0) AS TAX_Actual, CTE.LINE_ITEM_SALES - IFNULL(D.DISCOUNT,0) + CTE.SHIPPING_PRICE AS TOTAL_SALES, CASE WHEN R.QUANTITY IS NOT NULL THEN 1 ELSE 0 END AS IS_REFUND, R.total_refund_value as refund_value, R.last_refund_date as refund_date, R.quantity as refund_quantity, F.AWB AWB, F.SHIPPING_STATUS Shopify_Shipping_Status, F.SHIPPING_STATUS_UPDATE_DATE Shopify_Shipping_Updated_Date, F.COURIER SHOPIFY_COURIER, c.payment_mode FROM CTE LEFT JOIN medmongers_db.maplemonk.inyou_SHOPIFY_ALL_ORDERS_ITEMS_TAX T ON CTE.ORDER_ID = T.ORDER_ID AND CTE.LINE_ITEM_ID = T.LINE_ITEM_ID LEFT JOIN medmongers_db.maplemonk.inyou_Shopify_All_orders_items_discount D ON CTE.ORDER_ID = D.ORDER_ID AND CTE.LINE_ITEM_ID = D.LINE_ITEM_ID LEFT JOIN (SELECT ORDER_ID, LINE_ITEM_ID, SUM(subtotal) as total_refund_value, SUM(quantity) as quantity, MIN(refund_date) as first_refund_date, MAX(refund_date) as last_refund_date FROM medmongers_db.maplemonk.inyou_SHOPIFY_ALL_REFUNDS GROUP BY 1, 2 ) R ON CTE.ORDER_ID = R.ORDER_ID AND CTE.LINE_ITEM_ID = R.LINE_ITEM_ID LEFT JOIN medmongers_db.maplemonk.inyou_SHOPIFY_ALL_ORDERS_FULFILLMENT F ON CTE.ORDER_ID = F.ORDER_ID AND CTE.LINE_ITEM_ID = F.LINE_ITEM_ID left join (select * from( select *, row_number() over (partition by id, code order by 1) rw from medmongers_db.maplemonk.inyou_Shopify_All_discount_codes) where rw = 1) DC on CTE.order_id = DC.id left join ( select reference_code,payment_mode from medmongers_db.maplemonk.medmongers_unicommerce_fact_items qualify row_number()over(partition by reference_code order by SHIPPING_LAST_UPDATE_DATE desc) = 1 and lower(brand) like \'%inyou%\' ) c on lower(replace(cte.order_name,\'#\',\'\')) = lower(replace(c.reference_code,\'#\',\'\')) ; CREATE OR REPLACE TABLE medmongers_db.maplemonk.inyou_SHOPIFY_FACT_ITEMS_INTERMEDIATE AS SELECT O.SHOP_NAME, O.ORDER_ID, O.ORDER_NAME, O.CUSTOMER:id::int AS customer_id, O.Name, O.EMAIL, o.pincode, O.PHONE, O.Tags, O.LINE_ITEM_ID, O.SKU, O.PRODUCT_ID, O.cancelled_at, O.refund_date, O.refund_quantity, O.refund_value, O.CURRENCY, O.payment_gateway_names, o.payment_mode, O.IS_REFUND, CASE WHEN CD.city IS NULL OR CD.city = \'\' THEN \'NA\' ELSE upper(CD.city) END AS city, CASE WHEN CD.province IS NULL OR CD.province = \'\' THEN \'NA\' ELSE upper(CD.province) END AS state, CASE WHEN P.title = \'\' THEN \'NA\' ELSE P.title END AS product_name, CASE WHEN P.product_type = \'\' THEN \'NA\' ELSE P.product_type END AS category, O.order_status, O.order_timestamp, offer_price, O.LINE_ITEM_SALES, O.SHIPPING_PRICE, O.QUANTITY, O.TAX, O.TAX_Actual, O.TAX_RATE, O.DISCOUNT, O.DISCOUNT_BEFORE_TAX, O.GROSS_SALES_AFTER_TAX, O.GROSS_SALES_BEFORE_TAX, O.NET_SALES_BEFORE_TAX, O.TOTAL_SALES, O.Source, O.MOMENTS_COUNT, O.DAYSTOCONVERT, O.SHOPIFYQL_FIRSTVISIT_UTM_SOURCE, O.SHOPIFYQL_MAPPED_CHANNEL, O.SHOPIFYQL_LAST_MOMENT_UTM_SOURCE, O.Shopifyql_LAST_VISIT_NON_UTM_SOURCE, O.Shopifyql_FIRSTVISIT_UTM_MEDIUM, O.Shopifyql_LAST_MOMENT_UTM_MEDIUM, O.FINAL_UTM_CHANNEL, O.FINAL_UTM_CAMPAIGN, O.GOKWIK_UTM_MEDIUM, O.FINAL_UTM_SOURCE, o.final_utm_content, O.landingpageurl, O.Referrer_Name, O.AWB, O.SHOPIFY_SHIPPING_STATUS, O.SHOPIFY_SHIPPING_UPDATED_DATE, O.SHOPIFY_COURIER, O.Shopifyql_FIRSTVISIT_UTM_CAMPAIGN, O.Shopifyql_LAST_VISIT_UTM_CAMPAIGN, o.discount_code FROM medmongers_db.maplemonk.inyou_SHOPIFY_ALL_ORDERS_ITEMS O LEFT JOIN medmongers_db.maplemonk.inyou_Shopify_All_products P ON O.PRODUCT_ID = P.id LEFT JOIN(SELECT customer_id, city, province, row_number() OVER ( partition BY customer_id ORDER BY id DESC) rowid FROM medmongers_db.maplemonk.inyou_Shopify_All_customers_addresses) AS CD ON O.CUSTOMER:id::int = CD.customer_id AND CD.rowid = 1; CREATE OR REPLACE TABLE medmongers_db.maplemonk.inyou_SHOPIFY_FACT_ITEMS_TEMP_Category AS SELECT fi.* ,fi.SKU AS SKU_CODE ,coalesce(fi.product_name,sm.Product_name) as PRODUCT_NAME_Final ,coalesce(Upper(sm.Product_category),upper(fi.category)) AS Product_Category ,Upper(sm.Product_Sub_Category) as Product_Super_Category ,sm.MRP ,sm.brand ,sm.landing_cost ,sm.packaging_cost ,sm.tax_rate as sku_tax_rate FROM medmongers_db.maplemonk.inyou_SHOPIFY_FACT_ITEMS_INTERMEDIATE fi left join ( select upper(sku_code) as commonsku, upper(product_name) as product_name, upper(category) as product_category, upper(sub_category) as product_sub_category, landing_cost, mrp, brand, packaging_cost, tax_rate from medmongers_db.maplemonk.MEDMONGERS_FINAL_SKU_MASTER where brand = \'IN YOU\' qualify row_number() over (partition by upper(sku_code) order by brand desc) = 1 ) sm on lower(trim(sm.commonsku)) = lower(trim(fi.sku)); CREATE OR REPLACE TABLE medmongers_db.maplemonk.inyou_SHOPIFY_FACT_ITEMS_INTERMEDIATE AS SELECT * FROM medmongers_db.maplemonk.inyou_SHOPIFY_FACT_ITEMS_TEMP_Category; CREATE OR REPLACE TABLE medmongers_db.maplemonk.inyou_Shopify_Final_customerID AS WITH new_phone_numbers AS ( SELECT phone, contact_num, 19700000000 + ROW_NUMBER() OVER (ORDER BY contact_num ASC) AS maple_monk_id FROM ( SELECT DISTINCT RIGHT(REGEXP_REPLACE(REPLACE(phone, \' \', \'\'), \'[^a-zA-Z0-9]+\', \'\'), 10) AS contact_num, phone FROM medmongers_db.maplemonk.inyou_SHOPIFY_FACT_ITEMS_INTERMEDIATE ) a ), int_cte AS ( SELECT contact_num, email, COALESCE(maple_monk_id, id2) AS maple_monk_id FROM ( SELECT contact_num, email, maple_monk_id, 19800000000 + ROW_NUMBER() OVER (PARTITION BY CASE WHEN maple_monk_id IS NULL THEN 1 ELSE 0 END ORDER BY email ASC) AS id2 FROM ( SELECT DISTINCT COALESCE(p.contact_num, RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10)) AS contact_num, e.email, maple_monk_id FROM ( SELECT REPLACE(phone, \' \', \'\') AS contact_num, email FROM medmongers_db.maplemonk.inyou_SHOPIFY_FACT_ITEMS_INTERMEDIATE ) e LEFT JOIN new_phone_numbers p ON p.contact_num = RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10) ) a ) b ) SELECT contact_num, email, maple_monk_id FROM int_cte WHERE COALESCE(contact_num, email) IS NOT NULL; CREATE OR REPLACE TABLE medmongers_db.maplemonk.inyou_SHOPIFY_FACT_ITEMS AS SELECT COALESCE(m.maple_monk_id_phone, d.maple_monk_id) AS Shopify_customer_id_final, MIN(CAST(ORDER_TIMESTAMP AS DATE)) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS shopify_acquisition_date, MIN(CASE WHEN LOWER(order_status) NOT IN (\'cancelled\') THEN CAST(ORDER_TIMESTAMP AS DATE) END) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS shopify_first_complete_order_date, m.* FROM ( SELECT c.maple_monk_id AS maple_monk_id_phone, o.* FROM medmongers_db.maplemonk.inyou_SHOPIFY_FACT_ITEMS_INTERMEDIATE o LEFT JOIN ( SELECT contact_num AS phone, maple_monk_id FROM ( SELECT contact_num, maple_monk_id, ROW_NUMBER() OVER (PARTITION BY contact_num ORDER BY maple_monk_id ASC) AS magic FROM medmongers_db.maplemonk.inyou_Shopify_Final_customerID ) WHERE magic = 1 ) c ON c.phone = RIGHT(REGEXP_REPLACE(o.phone, \'[^a-zA-Z0-9]+\', \'\'), 10) ) m LEFT JOIN ( SELECT DISTINCT maple_monk_id, email FROM medmongers_db.maplemonk.inyou_Shopify_Final_customerID WHERE contact_num IS NULL ) d ON d.email = m.email; ALTER TABLE medmongers_db.maplemonk.inyou_SHOPIFY_FACT_ITEMS ADD COLUMN shopify_new_customer_flag STRING, shopify_new_customer_flag_month STRING, shopify_acquisition_product STRING, shopify_acquisition_channel STRING, shopify_acquisition_source STRING; UPDATE medmongers_db.maplemonk.inyou_SHOPIFY_FACT_ITEMS AS A SET shopify_new_customer_flag = B.flag FROM ( SELECT DISTINCT order_id, Shopify_customer_id_final, ORDER_TIMESTAMP, CASE WHEN TO_DATE(ORDER_TIMESTAMP) = shopify_first_complete_order_date THEN \'New\' WHEN TO_DATE(ORDER_TIMESTAMP) < shopify_first_complete_order_date OR shopify_first_complete_order_date IS NULL THEN \'Yet to make completed order\' WHEN TO_DATE(ORDER_TIMESTAMP) > shopify_first_complete_order_date THEN \'Repeat\' END AS flag FROM medmongers_db.maplemonk.inyou_SHOPIFY_FACT_ITEMS ) AS B WHERE A.order_id = B.order_id AND A.Shopify_customer_id_final = B.Shopify_customer_id_final AND TO_DATE(A.ORDER_TIMESTAMP) = TO_DATE(B.ORDER_TIMESTAMP); UPDATE medmongers_db.maplemonk.inyou_SHOPIFY_FACT_ITEMS SET shopify_new_customer_flag = CASE WHEN shopify_new_customer_flag IS NULL AND (CASE WHEN LOWER(order_status) IS NULL THEN TRUE ELSE LOWER(order_status) NOT IN (\'cancelled\') END) THEN \'New\' WHEN shopify_new_customer_flag IS NULL AND (CASE WHEN LOWER(order_status) IS NULL THEN TRUE ELSE LOWER(order_status) IN (\'cancelled\') END) THEN \'Yet to make completed order\' ELSE shopify_new_customer_flag END; UPDATE medmongers_db.maplemonk.inyou_SHOPIFY_FACT_ITEMS AS A SET shopify_new_customer_flag_month = B.flag FROM ( SELECT DISTINCT order_id, shopify_customer_id_final, TO_DATE(ORDER_TIMESTAMP) AS Order_Date, CASE WHEN LAST_DAY(TO_DATE(ORDER_TIMESTAMP)) = LAST_DAY(TO_DATE(shopify_first_complete_order_date)) THEN \'New\' WHEN LAST_DAY(TO_DATE(ORDER_TIMESTAMP)) < LAST_DAY(TO_DATE(shopify_first_complete_order_date)) OR shopify_acquisition_date IS NULL THEN \'Yet to make completed order\' WHEN LAST_DAY(TO_DATE(ORDER_TIMESTAMP)) > LAST_DAY(TO_DATE(shopify_first_complete_order_date)) THEN \'Repeat\' END AS Flag FROM medmongers_db.maplemonk.inyou_SHOPIFY_FACT_ITEMS ) AS B WHERE A.order_id = B.order_id AND A.shopify_customer_id_final = B.shopify_customer_id_final; UPDATE medmongers_db.maplemonk.inyou_SHOPIFY_FACT_ITEMS SET shopify_new_customer_flag_month = CASE WHEN shopify_new_customer_flag_month IS NULL AND (CASE WHEN LOWER(order_status) IS NULL THEN TRUE ELSE LOWER(order_status) NOT IN (\'cancelled\') END) THEN \'New\' ELSE shopify_new_customer_flag_month END; CREATE OR REPLACE TABLE medmongers_db.maplemonk.temp_source_1 AS SELECT shopify_customer_id_final, channel, source FROM ( SELECT DISTINCT shopify_customer_id_final, TO_DATE(order_timestamp) AS order_Date, FINAL_UTM_SOURCE AS SOURCE, FINAL_UTM_CHANNEL AS CHANNEL, MIN(CASE WHEN LOWER(order_status) NOT IN (\'cancelled\') THEN TO_DATE(order_timestamp) END) OVER (PARTITION BY shopify_customer_id_final) AS firstOrderdate, ROW_NUMBER() OVER(PARTITION BY shopify_customer_id_final ORDER BY 1 DESC) rw FROM medmongers_db.maplemonk.inyou_SHOPIFY_FACT_ITEMS ) res WHERE order_Date = firstOrderdate AND rw = 1; UPDATE medmongers_db.maplemonk.inyou_SHOPIFY_FACT_ITEMS AS a SET shopify_acquisition_channel = b.channel FROM medmongers_db.maplemonk.temp_source_1 b WHERE a.shopify_customer_id_final = b.shopify_customer_id_final; UPDATE medmongers_db.maplemonk.inyou_SHOPIFY_FACT_ITEMS AS a SET shopify_acquisition_source = b.source FROM medmongers_db.maplemonk.temp_source_1 b WHERE a.shopify_customer_id_final = b.shopify_customer_id_final; CREATE OR REPLACE TABLE medmongers_db.maplemonk.temp_product_1 AS SELECT DISTINCT shopify_customer_id_final, product_name_final, ROW_NUMBER() OVER (PARTITION BY shopify_customer_id_final ORDER BY total_sales DESC) AS rowid FROM ( SELECT DISTINCT shopify_customer_id_final, CAST(order_timestamp AS DATE) AS order_date, product_name_final, total_sales, MIN(CASE WHEN LOWER(order_status) NOT IN (\'cancelled\') THEN CAST(order_timestamp AS DATE) END) OVER (PARTITION BY shopify_customer_id_final) AS firstOrderdate FROM medmongers_db.maplemonk.inyou_SHOPIFY_FACT_ITEMS ) res WHERE order_date = firstOrderdate; UPDATE medmongers_db.maplemonk.inyou_SHOPIFY_FACT_ITEMS AS A SET shopify_acquisition_product = B.product_name_final FROM ( SELECT * FROM medmongers_db.maplemonk.temp_product_1 WHERE rowid = 1 ) B WHERE A.shopify_customer_id_final = B.shopify_customer_id_final; ALTER TABLE medmongers_db.maplemonk.inyou_SHOPIFY_FACT_ITEMS ADD COLUMN SHIPPING_TAX FLOAT, SHIP_PROMOTION_DISCOUNT FLOAT, GIFT_WRAP_PRICE FLOAT, GIFT_WRAP_TAX FLOAT;",
                    "transaction": true
                }
            ) }}
